import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { attemptResultUris, type Now, type Timeline } from '../../contracts/projects/triage.ts'
import { scopedResultPath, type RunDetail, type RunInputs, type ReviewResult, type RunScope, type WorkerResult, type WorkflowEvent } from './api.ts'
import { ChallengeSections } from './node/ChallengeSections.tsx'
import { AwaitingNotice, ControllerSections } from './node/ControllerSections.tsx'
import { attemptStrip, nodeTiming, resultRole, verifiedSections, workerSectionEntries, type SectionEntry } from './node/model.ts'
import { ReviewSections } from './node/ReviewSections.tsx'
import { CandidateLanes, VerifiedEvidence, WorkerReportLink, type LaneEntry } from './node/VerifySections.tsx'
import { WorkerSections } from './node/WorkerSections.tsx'
import { NodeHeader } from './NodeHeader.tsx'
import { AppLink, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { attemptPathname, runPathname } from './routes.ts'
import { NodeSection, SectionIndex } from './SectionIndex.tsx'
import { isChallengeNode } from './status.ts'
import { Time } from './Time.tsx'
import type { Resource } from './useResource.ts'
import { useRunResult, useRunResults } from './useRunData.ts'
import './node.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type ReviewTransport = ReviewResult['reviewer']['transport']

type Props = {
  scope: RunScope
  detail: RunDetail
  definition: DefinitionNode
  node: SnapshotNode
  /** The attempt the path names (`/attempts/<k>`); null shows the latest. */
  attempt: number | null
  events: Resource<WorkflowEvent[]>
  onRetryEvents: () => void
  /** The run's inputs (null once loaded when the export predates them), shared by every node of the run. */
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  /** The run's timeline, once its events loaded: the header's times, attempts and markers. */
  timeline: Timeline | null
  /** The run's situation, once derived: its next step is repeated on the focus node. */
  now: Now | null
  clock: number
  refreshToken: number
  onNavigate: (pathname: string) => void
  /** A requirement quote to highlight in this node's task, handed over by a review finding link. */
  highlight: string | null
  onHighlightApplied: () => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  /** A captured file to scroll to on this launch node, handed over by a review finding's file link. */
  fileFocus: string | null
  onFileFocusApplied: () => void
  onOpenFile: (nodeId: string, path: string) => void
}

/**
 * One node of a run (docs/PRD_VIEWER_UX.md 4.4-4.9): the header (status by cause, timing, attempts, next step), a section
 * index with counts, then the sections of its kind (worker, verification, candidate, review, challenge or the controller's
 * own steps) and History, always last. Empty sections are absent; a result the launch and verify nodes share is said once.
 * An earlier attempt's page shows that attempt's own result under a banner that leads back to the latest.
 */
export function NodeDetail({ scope, detail, definition, node, attempt, events, onRetryEvents, inputs, onRetryInputs, timeline, now, clock, refreshToken, onNavigate, highlight, onHighlightApplied, onOpenRequirement, fileFocus, onFileFocusApplied, onOpenFile }: Props) {
  const definitionNodes = detail.definition.nodes
  const snapshotNodes = detail.snapshot.nodes
  // A review's executor wording depends on the transport its served result records, known once the review panel loads it.
  const [reviewTransport, setReviewTransport] = useState<ReviewTransport | undefined>(undefined)

  const isWorker = definition.kind === 'worker'
  const isChallenge = isChallengeNode(definition)
  const isReview = definition.kind === 'review' && !isChallenge
  const isCandidate = node.node_id === 'candidate'
  const isVerify = definition.kind === 'verification' && !isCandidate
  const isController = definition.kind === 'prepare' || definition.kind === 'integration'
  const latest = node.attempt
  const isLatest = attempt === null || attempt === latest
  const shownAttempt = attempt ?? latest
  const recorded = shownAttempt >= 1 && shownAttempt <= latest

  // What this view reads: the latest attempt's result as served, or the viewed attempt's own (`results/<lane>/<k>`).
  const attemptUris = useMemo(() => attemptResultUris(detail, node.node_id), [detail, node.node_id])
  const resultUri = definition.kind === 'review' ? null
    : isLatest || !isVerify ? node.result_uri
      : attemptUris.find(item => item.attempt === attempt)?.uri ?? null
  const lanes: LaneEntry[] = isLatest || !isCandidate ? node.lane_results
    : attemptUris.filter(item => item.attempt === attempt).map(item => ({ worker: item.lane, attempt: item.attempt, result_uri: item.uri }))
  const resultPath = resultUri === null ? null : scopedResultPath(scope, resultUri)
  const stamp = String(refreshToken)
  const { state: result, reload: reloadResult } = useRunResult(scope, resultPath, stamp)
  const resultData = result.status === 'ready' ? result.data : null

  // The attempt strip: a chip shows once one of its results loaded (read through the run's cache, asked again on new events).
  const strip = useMemo(() => (timeline ? attemptStrip(detail, timeline, node.node_id) : []), [detail, timeline, node.node_id])
  const chipUris = useMemo(() => strip.flatMap(item => (item.kind === 'attempt' ? item.chip.uris : [])), [strip])
  const { results: chipResults } = useRunResults(scope, chipUris, `${refreshToken}:${detail.snapshot.last_sequence}`)
  const loaded = useCallback((uri: string) => chipResults.has(uri), [chipResults])
  const viewedChip = strip.flatMap(item => (item.kind === 'attempt' && item.chip.attempt === shownAttempt ? [item.chip] : []))[0]

  // The candidate's own verdict is its lanes': a failing lane's gate reasons are the cause its header names.
  const { results: laneResults } = useRunResults(scope, useMemo(() => lanes.map(entry => entry.result_uri), [lanes]), stamp)
  const failure = lanes.flatMap(entry => {
    const error = laneResults.get(entry.result_uri)?.error
    return error ? [`${entry.worker}: ${error.message}`] : []
  }).join('; ') || null

  const nodeEvents = events.status === 'ready' ? events.data.filter(event => event.node_id === node.node_id) : []
  const reuse = nodeEvents.filter(event => event.type === 'result_reused')
  const approvals = nodeEvents.filter(event => event.type === 'approval_requested')

  const recordedInputs = inputs.status === 'ready' ? inputs.data : null
  const worker = isWorker && recordedInputs !== null ? recordedInputs.workers.find(candidate => candidate.launch_node_id === node.node_id) ?? null : null
  // The design challenge is also of kind review; the independent review is the other one.
  const reviewNode = snapshotNodes.find(candidate => candidate.kind === 'review' && !isChallengeNode(candidate)) ?? null
  const hasNode = (nodeId: string) => definitionNodes.some(candidate => candidate.node_id === nodeId)
  const nodeLink = (nodeId: string) => ({ node_id: nodeId, href: runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId), label: definitionNodes.find(candidate => candidate.node_id === nodeId)!.label })
  const launchNodeOf = (lane: string) => {
    const launched = recordedInputs?.workers.find(candidate => candidate.node_id === lane)?.launch_node_id
    const id = launched && hasNode(launched) ? launched : hasNode(`launch_${lane}`) ? `launch_${lane}` : null
    return id === null ? null : nodeLink(id)
  }
  const lane = isWorker ? worker?.node_id ?? node.node_id.replace(/^launch_/, '') : null
  const verifyNode = lane !== null && hasNode(`verify_${lane}`) ? nodeLink(`verify_${lane}`) : null
  const role = resultRole(detail, node.node_id)
  const reportNode = isVerify && !role.narrative && role.partner !== null ? nodeLink(role.partner) : null
  const repairs = (timeline?.markers ?? []).filter(marker => marker.kind === 'repair' && verifyNode !== null && marker.node_id === verifyNode.node_id)
  const repairNote = repairs.length ? `after operator ${repairs.map(marker => `repair ${marker.repair?.n ?? ''}`.trim()).join(', ')}` : ''

  const timing = timeline && recorded ? nodeTiming(timeline, node.node_id, isLatest ? null : attempt, isVerify ? resultData : null) : null
  const headerStatus = isLatest ? node.status : viewedChip?.status ?? resultData?.status ?? 'pending'
  const next = isLatest && now?.focus?.node_id === node.node_id && (now.next.steps.length > 0 || now.next.action === 'required') ? now.next : null
  const attemptHref = (value: number) => attemptPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id, value)
  const nodeHref = runPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id)

  const renderResult = (evidence: (data: WorkerResult) => ReactNode) => (
    <>
      {resultUri === null && lanes.length === 0 && <p className="projects-muted" data-testid="result-none">No result has been published for this node{node.attempt === 0 ? ' (it has not started)' : ''}.</p>}
      {resultUri !== null && resultPath === null && (
        <p className="projects-error-inline" role="alert" data-testid="result-unscoped">
          The result link <code>{resultUri}</code> is outside this run's results route and was not fetched.
        </p>
      )}
      {resultPath !== null && result.status === 'loading' && <LoadingPanel>Loading the result…</LoadingPanel>}
      {resultPath !== null && result.status === 'error' && <ErrorPanel error={result.error} what="The node result" onRetry={reloadResult} />}
      {resultPath !== null && result.status === 'ready' && evidence(result.data)}
    </>
  )

  // The section index: what the kind lists, only when it lists something, then reuse (only with reuse events) and History.
  const sections: SectionEntry[] = [
    ...(isWorker ? workerSectionEntries(worker, resultData) : []),
    ...(isCandidate && lanes.length > 0 ? [{ key: 'lanes', label: 'Lanes', count: lanes.length }] : []),
    ...((isVerify || isCandidate) && resultData !== null ? verifiedSections(resultData) : []),
    ...(isReview ? [{ key: 'review', label: 'Review' }] : []),
    ...(isChallenge ? [{ key: 'challenge', label: 'Challenge' }] : []),
    ...(reuse.length > 0 ? [{ key: 'reuse', label: 'Reuse', count: reuse.length }] : []),
    { key: 'history', label: 'History', ...(events.status === 'ready' ? { count: nodeEvents.length } : {}) },
  ]
  // An earlier attempt keeps only a verification's own result; any other step's earlier attempt shows its times and History.
  const evidence = isLatest || (recorded && (isVerify || isCandidate))

  return (
    <section className="node-detail" aria-labelledby="node-detail-title" data-testid="node-detail" data-node-id={node.node_id} data-attempt={isLatest ? undefined : shownAttempt}>
      <NodeHeader
        definition={definition}
        status={headerStatus}
        attempt={shownAttempt}
        timing={timing}
        clock={clock}
        events={nodeEvents}
        timeline={timeline}
        result={resultData}
        failure={failure}
        reviewTransport={reviewTransport}
        verifyNode={verifyNode}
        strip={strip}
        loaded={loaded}
        attemptHref={attemptHref}
        next={next}
        onNavigate={onNavigate}
      />

      {!isLatest && (
        <p className="projects-notice attempt-banner" role="note" data-testid="attempt-banner">
          {recorded ? `You are viewing attempt ${attempt} of ${latest}. ` : `Attempt ${attempt} of this step was not recorded. `}
          <AppLink href={nodeHref} onNavigate={onNavigate}>{latest === 0 ? 'Open the step ›' : `The latest is attempt ${latest} ›`}</AppLink>
        </p>
      )}

      {isLatest && node.status === 'awaiting_approval' && <AwaitingNotice approvals={approvals} />}

      {!isController && (isLatest || recorded) && (
        <SectionIndex label={definition.label} sections={evidence ? sections : sections.filter(section => section.key === 'history')}>
          {reportNode && <WorkerReportLink href={reportNode.href} label={reportNode.label} onNavigate={onNavigate} />}
        </SectionIndex>
      )}

      {!evidence && recorded && <p className="projects-muted" data-testid="attempt-latest-only">Only the latest attempt's evidence is kept for this step; the times above are this attempt's.</p>}

      {evidence && (
        isWorker ? (
          <WorkerSections
            scope={scope}
            renderResult={renderResult}
            result={result}
            role={role}
            checksNode={verifyNode}
            repairNote={repairNote}
            inputs={inputs}
            onRetryInputs={onRetryInputs}
            worker={worker}
            reviewNode={reviewNode}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            highlight={highlight}
            onHighlightApplied={onHighlightApplied}
            fileFocus={fileFocus}
            onFileFocusApplied={onFileFocusApplied}
          />
        ) : isChallenge ? (
          <ChallengeSections inputs={inputs} onRetryInputs={onRetryInputs} />
        ) : isReview ? (
          <ReviewSections
            scope={scope}
            node={node}
            definitionNodes={definitionNodes}
            snapshotNodes={snapshotNodes}
            inputs={inputs}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            onOpenRequirement={onOpenRequirement}
            onOpenFile={onOpenFile}
            onTransport={setReviewTransport}
          />
        ) : isController ? (
          <ControllerSections scope={scope} renderResult={renderResult} />
        ) : (
          <>
            {lanes.length > 0 && <CandidateLanes scope={scope} lanes={lanes} launchNodeOf={launchNodeOf} stamp={stamp} onNavigate={onNavigate} />}
            {renderResult(data => <VerifiedEvidence scope={scope} result={data} phase="worker" anchored />)}
          </>
        )
      )}

      {reuse.length > 0 && (
        <NodeSection sectionKey="reuse" title="Reuse evidence">
          <ul className="evidence-list" data-testid="reuse-list">
            {reuse.map(event => (
              <li key={event.event_id}>
                Attempt {event.attempt} reused the result of attempt {event.reused_from_attempt ?? 'unknown'} (event {event.sequence}, <Time iso={event.occurred_at} seconds />): {event.message}
              </li>
            ))}
          </ul>
        </NodeSection>
      )}

      <NodeSection sectionKey="history" title="History">
        {events.status === 'loading' && <LoadingPanel>Loading events…</LoadingPanel>}
        {events.status === 'error' && <ErrorPanel error={events.error} what="The run events" onRetry={onRetryEvents} />}
        {events.status === 'ready' && (nodeEvents.length === 0 ? (
          <p className="projects-muted" data-testid="events-none">No events reference this node.</p>
        ) : (
          <ol className="event-list" data-testid="node-events">
            {nodeEvents.map(event => (
              <li key={event.event_id} data-attempt={event.attempt}>
                <span className="event-seq">#{event.sequence}</span> <span className="projects-muted"><Time iso={event.occurred_at} seconds /></span>{' '}
                <span className="event-type">{event.type.replace(/_/g, ' ')}</span>
                {event.status && <> · <StatusBadge status={event.status} /></>}
                {event.attempt > 0 && <> · attempt {event.attempt}</>}
                {event.message && <> — {event.message}</>}
                {event.artifact && <> · artifact <code>{event.artifact.artifact_id}</code> ({event.artifact.kind})</>}
              </li>
            ))}
          </ol>
        ))}
      </NodeSection>
    </section>
  )
}
  const openRequirement = useCallback((nodeId: string, quote: string) => {
    setPendingHighlight({ nodeId, quote })
    onNavigate(nodeHref(nodeId))
  }, [onNavigate, nodeHref])
  const openFile = useCallback((nodeId: string, path: string) => {
    setPendingFile({ nodeId, path })
    onNavigate(nodeHref(nodeId))
  }, [onNavigate, nodeHref])

  const onTabKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    onNavigate(tabHref(TABS[next].id))
    event.currentTarget.parentElement?.querySelector<HTMLButtonElement>(`[data-testid="${TABS[next].testId}"]`)?.focus()
  }

  // Selecting a step opens its page at the top with the focus on its heading; coming back focuses the step's row again.
  const shownNode = useRef(selectedNodeId)
  useEffect(() => {
    const previous = shownNode.current
    shownNode.current = selectedNodeId
    if (previous === selectedNodeId) return
    if (selectedNodeId !== null) {
      window.scrollTo(0, 0)
      document.getElementById('node-detail-title')?.focus({ preventScroll: true })
    } else if (previous !== null) {
      document.querySelector<HTMLElement>(`[data-testid="run-node-list"] [data-node-id="${CSS.escape(previous)}"] a`)?.focus()
    }
  }, [selectedNodeId])

  // While a question, a pane or an approval waits on the operator, the tab title says so (docs/PRD_VIEWER_UX.md 6.4).
  const waiting = attention?.top != null
  useEffect(() => {
    if (!waiting) return
    const title = document.title
    document.title = `? Waiting · ${summary.run_id} — ${title}`
    return () => { document.title = title }
  }, [waiting, summary.run_id])

  // The polite announcer speaks the Now headline only when the situation changes, never on a poll that changed nothing.
  const situation = now?.situation ?? null
  const spoken = useRef<string | null>(null)
  useEffect(() => {
    if (now === null) return
    const previous = spoken.current
    spoken.current = now.situation
    if (previous === null || previous === now.situation) return
    const format = { clock: (at: string) => formatClock(at, { zone, reference: runStart }), ago: formatAgo, span: formatSpan }
    onAnnounce(`Now: ${textToString(withoutGlyph(now.headline, now.glyph), Date.now(), format)}`)
    // Only a change of situation speaks; the headline's clock and ages change every second.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [situation])

  const tabs = (
    <div className="tabs run-tabs" role="tablist" aria-label="Run views">
      {TABS.map(candidate => (
        <button
          key={candidate.id}
          type="button"
          role="tab"
          id={`run-tab-${candidate.id}`}
          className="tab"
          aria-selected={tab === candidate.id}
          aria-controls={`run-panel-${candidate.id}`}
          tabIndex={tab === candidate.id ? 0 : -1}
          data-testid={candidate.testId}
          onClick={() => { if (tab !== candidate.id || selectedNodeId !== null) onNavigate(tabHref(candidate.id)) }}
          onKeyDown={onTabKey}
        >
          {candidate.label}
        </button>
      ))}
    </div>
  )

import { useState, type ReactNode } from 'react'
import type { RunDetail, RunInputs, RunInputWorker, RunScope, WorkerResult } from '../api.ts'
import { CreatedFiles } from '../CreatedFiles.tsx'
import { AppLink, ErrorPanel, LoadingPanel } from '../panels.tsx'
import { NodeSection } from '../SectionIndex.tsx'
import type { Resource } from '../useResource.ts'
import { LaunchReceipt, StopLine, TaskPanel, WorkerQuestions, WorkerSignals } from '../WorkerInputs.tsx'
import { filesCount } from './model.ts'
import type { CheckTarget } from './Requirements.tsx'
import { ResultError, ResultFacts, WorkerNarrative } from './ResultFacts.tsx'
import './worker.css'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]

/** The pinned task behind a disclosure, closed by default and opened when a finding link hands over a quote to highlight. */
function TaskDisclosure({ highlight, children }: { highlight: string | null; children: ReactNode }) {
  const [open, setOpen] = useState(highlight !== null)
  return (
    <details className="evidence-section task-details" data-testid="task-details" open={open} onToggle={event => setOpen(event.currentTarget.open)}>
      <summary id="task-details-summary">Task: what this worker was asked to do</summary>
      {children}
    </details>
  )
}

type Props = {
  scope: RunScope
  /** The node's result as loaded, with its loading, error and absence lines already worded. */
  renderResult: (evidence: (data: WorkerResult) => ReactNode) => ReactNode
  result: Resource<WorkerResult>
  /** Whether this node shows the result's facts (no verify node links the same result) and the worker's narrative. */
  role: { facts: boolean; narrative: boolean }
  /** The verify node that shows the result's facts and executed checks; null when the pinned graph has none. */
  checksNode: CheckTarget | null
  /** "after operator repair 1" when the verify node's latest attempt followed a repair; empty otherwise. */
  repairNote: string
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  worker: RunInputWorker | null
  reviewNode: SnapshotNode | null
  refreshToken: number
  onNavigate: (pathname: string) => void
  highlight: string | null
  onHighlightApplied: () => void
  fileFocus: string | null
  onFileFocusApplied: () => void
}

/**
 * A launch node's sections (docs/PRD_VIEWER_UX.md 4.5): the questions to the operator while there are any, what the worker
 * produced (its narrative, and the result's facts unless the verify node shows them) and the files it created or changed
 * as captured at freeze, then its completion signal, the launch receipt and the task behind a disclosure.
 */
export function WorkerSections({ scope, renderResult, result, role, checksNode, repairNote, inputs, onRetryInputs, worker, reviewNode, refreshToken, onNavigate, highlight, onHighlightApplied, fileFocus, onFileFocusApplied }: Props) {
  const recordedInputs = inputs.status === 'ready' ? inputs.data : null
  const files = result.status === 'ready' ? filesCount(result.data) : 0
  return (
    <>
      {worker !== null && worker.questions.length > 0 && (
        <NodeSection sectionKey="questions" labelledBy="worker-questions-title">
          <WorkerQuestions questions={worker.questions} />
        </NodeSection>
      )}

      <NodeSection sectionKey="result" title="Result">
        {renderResult(data => (
          <div className="worker-evidence" data-testid="worker-result" data-view="produced">
            {!role.facts && checksNode !== null && (
              <p className="worker-verified" data-testid="worker-verified">
                Verified on attempt {data.attempt}{repairNote ? ` ${repairNote}` : ''}
                {data.output_commit ? <> · revision <code>{data.output_commit.slice(0, 7)}</code></> : null} ·{' '}
                <AppLink href={checksNode.href} onNavigate={onNavigate}>facts and checks on {checksNode.label} ›</AppLink>
              </p>
            )}
            {role.narrative && <WorkerNarrative result={data} />}
            {role.facts && <><ResultFacts result={data} /><ResultError result={data} /></>}
          </div>
        ))}
      </NodeSection>

      {result.status === 'ready' && files > 0 && (
        <NodeSection sectionKey="files" labelledBy="evidence-created-files">
          <CreatedFiles scope={scope} result={result.data} reviewNode={reviewNode} refreshToken={refreshToken} focusPath={fileFocus} onFocusApplied={onFileFocusApplied} />
        </NodeSection>
      )}

      {(inputs.status === 'loading' || inputs.status === 'idle') && <LoadingPanel>Loading the run inputs…</LoadingPanel>}
      {inputs.status === 'error' && <ErrorPanel error={inputs.error} what="The run inputs" onRetry={onRetryInputs} />}
      {inputs.status === 'ready' && recordedInputs === null && (
        <p className="projects-muted" data-testid="worker-inputs-none">
          Inputs not recorded for this run (the export predates run inputs; re-export it with the workflow CLI), so the task, launch receipt and completion signal cannot be shown.
        </p>
      )}
      {recordedInputs !== null && worker === null && (
        <p className="projects-muted" data-testid="worker-inputs-unmatched">The run inputs list no worker launched by this node.</p>
      )}
      {worker !== null && (
        <>
          <NodeSection sectionKey="report" labelledBy="worker-completion-title">
            <WorkerSignals completion={worker.completion} handoff={worker.handoff} worker={worker} result={result} checksNode={checksNode} onNavigate={onNavigate} />
          </NodeSection>
          <NodeSection sectionKey="session" labelledBy="launch-receipt-title">
            <LaunchReceipt launch={worker.launch} />
            {worker.questions.length === 0 && <p className="projects-muted" data-testid="worker-questions-none">No questions were recorded for this worker.</p>}
            <StopLine stop={worker.stop} />
          </NodeSection>
          <NodeSection sectionKey="task" labelledBy="task-details-summary">
            <TaskDisclosure highlight={highlight}>
              <TaskPanel worker={worker} result={result} highlight={highlight} onHighlightApplied={onHighlightApplied} checksNode={checksNode} onNavigate={onNavigate} />
            </TaskDisclosure>
          </NodeSection>
        </>
      )}
    </>
  )
}
import type { ReactNode } from 'react'
import { humanizeEvent, type Now, type SpanStatus, type Timeline } from '../../contracts/projects/triage.ts'
import type { ReviewResult, RunDetail, WorkerResult, WorkflowEvent } from './api.ts'
import { CommandBlock } from './CommandBlock.tsx'
import { attemptWord, type StripItem, type Timing } from './node/model.ts'
import { AppLink, StatusBadge } from './panels.tsx'
import { executorCategory, executorOf, STATUS_LABEL } from './status.ts'
import { STATUS_GLYPH } from './steps.ts'
import { Time } from './Time.tsx'
import { formatSpan } from './time.ts'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type NodeStatus = RunDetail['snapshot']['nodes'][number]['status']
type Link = { href: string; label: string }

/** The words of a span status, for attempt chips; "ended without a record" has no badge of its own. */
const SPAN_WORD: Record<SpanStatus, string> = { ...Object.fromEntries(Object.entries(STATUS_LABEL).map(([key, label]) => [key, label.toLowerCase()])) as Record<NodeStatus, string>, no_record: 'ended without a record' }
const SPAN_GLYPH: Record<SpanStatus, string> = { ...STATUS_GLYPH, no_record: '?' }

const sentence = (text: string) => (/[.!?]$/.test(text) ? text : `${text}.`)

/**
 * What the step's status means, worded by its cause (docs/PRD_VIEWER_UX.md 8). The pinned phrases stay: "This step failed",
 * "This is not workflow completion". A worker's success links the verification that proves it; a verification that passed
 * after earlier attempts says so, and after which repair.
 */
function statusCause({ kind, status, attempt, cause, repairs, verifyNode, onNavigate }: {
  kind: DefinitionNode['kind']
  status: NodeStatus | 'no_record'
  attempt: number
  /** The latest status message of the shown attempt, humanized; null when none was recorded. */
  cause: string | null
  /** The operator's repairs recorded before the shown attempt. */
  repairs: number[]
  verifyNode: Link | null
  onNavigate: (pathname: string) => void
}): ReactNode {
  switch (status) {
    case 'pending': return 'Not started: no attempt has run.'
    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : `In progress${cause ? `: ${sentence(cause)}` : '.'}`
    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
    case 'paused': return `Paused${cause ? `: ${sentence(cause)}` : ' with unresolved evidence.'} Not complete.`
    case 'no_record': return 'This attempt ended without a record: a later attempt replaced it before any verdict.'
    case 'cancelled': return 'This step was cancelled.'
    case 'failed': return `This step failed.${cause ? ` ${sentence(cause)}` : ' The run cannot succeed without intervention.'}`
    case 'succeeded':
      if (kind === 'worker') {
        return verifyNode
          ? <>Session ended its turn. This is not workflow completion — verified by <AppLink href={verifyNode.href} onNavigate={onNavigate}>{verifyNode.label} ›</AppLink></>
          : 'Session ended its turn. This is not workflow completion; verification, review and integration are separate steps.'
      }
      if (kind === 'integration') return 'This integration step completed.'
      if (attempt > 1) return `Passed on attempt ${attempt}${repairs.length ? ` after operator ${repairs.map(n => `repair ${n}`).join(', ')}` : ''}.`
      return 'This step completed.'
  }
}

/** The timing line's times: start → end, how long, and the setup and check split; `≈` and a tooltip for inferred times. */
function TimingText({ timing, clock }: { timing: Timing; clock: number }) {
  const { start, end, live } = timing
  const elapsed = live && start ? Math.max(0, clock - Date.parse(start.at)) : null
  // A step recorded by one event (the freeze, a verdict with no start) is an instant: one time, no duration.
  const instant = start !== null && end !== null && start.at === end.at
  const took = instant ? null : timing.ms ?? elapsed
  return (
    <>
      {start && <> · <span title={start.note}>{start.source === 'inferred' ? '≈' : ''}<Time iso={start.at} seconds /></span></>}
      {end && !instant && <> → <span title={end.note}>{end.source === 'inferred' ? '≈' : ''}<Time iso={end.at} seconds /></span></>}
      {took !== null && <> · <span className="node-timing-took">{live ? 'running ' : ''}{timing.inferred ? '≈' : ''}{formatSpan(took)}</span></>}
      {timing.setupMs !== null && <> · setup {formatSpan(timing.setupMs)}</>}
      {timing.checksMs !== null && <> · checks {formatSpan(timing.checksMs)}</>}
      {timing.source && <span className="projects-muted node-timing-source"> ({timing.source})</span>}
    </>
  )
}

/**
 * The attempt strip (docs/PRD_VIEWER_UX.md 4.4): each attempt as a chip that links its own page, once its result loaded
 * (a chip whose results are loading or missing is not shown; a step that keeps no results shows its chips unlinked), with
 * the controller's diagnosis (⚑) and the operator's repairs (⚒) between the attempts they concern.
 */
function AttemptStrip({ items, loaded, shown, attemptHref, onNavigate }: {
  items: StripItem[]
  loaded: (uri: string) => boolean
  shown: number
  attemptHref: (attempt: number) => string
  onNavigate: (pathname: string) => void
}) {
  return (
    <div className="node-attempts" data-testid="node-attempts">
      <span className="node-attempts-label">Attempts</span>
      <ul className="node-attempts-list">
        {items.map(item => {
          if (item.kind !== 'attempt') {
            return (
              <li key={`${item.kind}-${item.at}`}>
                <span className={`node-attempt-marker node-attempt-${item.kind}`} data-item={item.kind} title={item.message}>
                  <span aria-hidden="true">{item.kind === 'diagnosis' ? '⚑' : '⚒'}</span> {item.label}
                </span>
              </li>
            )
          }
          const { chip } = item
          const linked = chip.uris.length > 0
          if (linked && !chip.uris.some(loaded)) return null
          const content = (
            <>
              <span className={`status-text-${chip.status === 'no_record' ? 'pending' : chip.status}`} aria-hidden="true">#{chip.attempt} {SPAN_GLYPH[chip.status]}</span>
              {chip.start && <> <Time iso={chip.start.at} /></>}
              {chip.ms !== null && <> · {formatSpan(chip.ms)}</>}
            </>
          )
          const name = `Attempt ${chip.attempt}, ${SPAN_WORD[chip.status]}${chip.ms !== null ? `, ${formatSpan(chip.ms)}` : ''}`
          return (
            <li key={`attempt-${chip.attempt}`}>
              {linked ? (
                <AppLink href={attemptHref(chip.attempt)} onNavigate={onNavigate} current={chip.attempt === shown} className="node-attempt-chip" data-item="attempt" data-attempt={chip.attempt} aria-label={name} title={chip.outcome || undefined}>
                  {content}
                </AppLink>
              ) : (
                <span className="node-attempt-chip" data-item="attempt" data-attempt={chip.attempt} aria-label={name} title={chip.outcome || undefined}>{content}</span>
              )}
            </li>
          )
        })}
      </ul>
    </div>
  )
}

type Props = {
  definition: DefinitionNode
  /** The status and attempt shown: the node's own, or the viewed earlier attempt's. */
  status: NodeStatus | 'no_record'
  attempt: number
  timing: Timing | null
  clock: number
  /** The node's events, for the cause of its status. */
  events: WorkflowEvent[]
  timeline: Timeline | null
  result: WorkerResult | null
  /** The failure's cause when the node's own result does not carry it: the failing lanes' gate reasons on the candidate. */
